import { describe, it, mock } from "node:test";
import assert from "node:assert";
import { processWebhookEventBackground } from "../business/webhooks/processor";
import { prisma as db } from "../lib/db/prisma";

describe("Webhook Processor Mappings", () => {
  it("should correctly map refund events", async () => {
    let capturedData: any = null;
    const originalTx = db.$transaction;
    
    // 
    db.$transaction = (async (callback: any) => {
      const txMock = {
        financialEvent: {
          create: async ({ data }: any) => {
            capturedData = data;
          }
        }
      };
      await callback(txMock);
    }) as any;

    await processWebhookEventBackground("evt_1", "refund.created", {
      created_at: 1000,
      payload: {
        refund: {
          entity: {
            id: "ref_123",
            payment_id: "pay_123",
            amount: 500,
            currency: "INR"
          }
        }
      }
    });

    assert.ok(capturedData);
    assert.strictEqual(capturedData.eventType, "refund.created");
    assert.strictEqual(capturedData.sourceId, "ref_123");
    assert.strictEqual(capturedData.refundId, "ref_123");
    assert.strictEqual(capturedData.paymentId, "pay_123");
    assert.strictEqual(capturedData.amountSubunits, 500);
    
    // 
    db.$transaction = originalTx as any;
  });

  it("should correctly map dispute events", async () => {
    let capturedData: any = null;
    const originalTx = db.$transaction;
    
    // 
    db.$transaction = (async (callback: any) => {
      const txMock = {
        financialEvent: {
          create: async ({ data }: any) => {
            capturedData = data;
          }
        }
      };
      await callback(txMock);
    }) as any;

    await processWebhookEventBackground("evt_2", "payment.dispute.created", {
      created_at: 1000,
      payload: {
        dispute: {
          entity: {
            id: "disp_123",
            payment_id: "pay_123",
            amount: 500,
            currency: "INR"
          }
        }
      }
    });

    assert.ok(capturedData);
    assert.strictEqual(capturedData.eventType, "payment.dispute.created");
    assert.strictEqual(capturedData.sourceId, "disp_123");
    assert.strictEqual(capturedData.disputeId, "disp_123");
    assert.strictEqual(capturedData.paymentId, "pay_123");
    
    // 
    db.$transaction = originalTx as any;
  });

  it("should correctly map invoice events", async () => {
    let capturedData: any = null;
    const originalTx = db.$transaction;
    
    // 
    db.$transaction = (async (callback: any) => {
      const txMock = {
        financialEvent: {
          create: async ({ data }: any) => {
            capturedData = data;
          }
        }
      };
      await callback(txMock);
    }) as any;

    await processWebhookEventBackground("evt_3", "invoice.payment_failed", {
      created_at: 1000,
      payload: {
        invoice: {
          entity: {
            id: "inv_123",
            order_id: "order_123",
            customer_id: "cust_123",
            subscription_id: "sub_123",
            amount: 500,
            currency: "INR"
          }
        }
      }
    });

    assert.ok(capturedData);
    assert.strictEqual(capturedData.eventType, "invoice.payment_failed");
    assert.strictEqual(capturedData.sourceId, "inv_123");
    assert.strictEqual(capturedData.invoiceId, "inv_123");
    assert.strictEqual(capturedData.orderId, "order_123");
    assert.strictEqual(capturedData.subscriptionId, "sub_123");
    
    // 
    db.$transaction = originalTx as any;
  });
});

import { NextResponse } from "next/server";
import crypto from "crypto";
import { prisma as db } from "@/lib/db/prisma";
import { env } from "@/lib/config/env";
import { processWebhookEventBackground } from "@/business/webhooks/processor";

export async function POST(req: Request) {
  try {
    const rawBody = await req.text();
    const signature = req.headers.get("x-razorpay-signature");
    const eventId = req.headers.get("x-razorpay-event-id");

    if (!signature || !eventId) {
      return NextResponse.json({ error: "Missing required headers" }, { status: 400 });
    }

    // 1. Signature Validation using raw body
    const expectedSignature = crypto
      .createHmac("sha256", env.RAZORPAY_WEBHOOK_SECRET!)
      .update(rawBody)
      .digest("hex");

    if (signature !== expectedSignature) {
      return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
    }

    // 2. Idempotency Check using WebhookEvent
    const existingEvent = await db.webhookEvent.findUnique({
      where: { razorpayEventId: eventId },
    });

    if (existingEvent) {
      return NextResponse.json({ status: "skipped", reason: "duplicate" }, { status: 200 });
    }

    // Parse payload after signature validation
    let payload;
    try {
      payload = JSON.parse(rawBody);
    } catch (_e) {
      return NextResponse.json({ error: "Invalid JSON payload" }, { status: 400 });
    }

    const event = payload.event;

    const supportedEvents = [
      "payment.authorized", "payment.captured", "payment.failed",
      "order.paid",
      "payment_link.paid", "payment_link.partially_paid", "payment_link.cancelled", "payment_link.expired",
      "subscription.charged", "subscription.halted", "subscription.cancelled"
    ];

    if (!supportedEvents.includes(event)) {
      return NextResponse.json({ status: "ignored", reason: "unsupported event" }, { status: 200 });
    }

    // 3. Webhook Replay / Age Check (Observability flag, do not reject legitimate delayed events)
    const eventCreatedAt = payload.created_at ? payload.created_at * 1000 : null;
    if (eventCreatedAt && (Date.now() - eventCreatedAt > 24 * 60 * 60 * 1000)) {
      console.warn(`[OBSERVABILITY] Webhook event ${eventId} is unusually old (created_at: ${new Date(eventCreatedAt).toISOString()}). Proceeding with ingestion.`);
    }

    // 4. Ingestion (Separate from processing)
    await db.webhookEvent.create({
      data: {
        razorpayEventId: eventId,
        event: event,
        payload: payload,
        processed: true, // marked true as it will be processed immediately after
      },
    });

    // 5. Asynchronous Processing (Return 200 promptly)
    processWebhookEventBackground(eventId, event, payload).catch(error => {
      console.error(`[WEBHOOK_PROCESSOR_ERROR] Failed to process event ${eventId}:`, error);
    });

    return NextResponse.json({ status: "processed" }, { status: 200 });
  } catch (error: unknown) {
    console.error("Webhook processing error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { z } from "zod";
import { generateObject } from "ai";
import { AI_MODELS } from "../../ai/config";
import { AbandonmentCandidate } from "./detector";

export const CheckoutAbandonmentAIOutputSchema = z.object({
  recommendedAction: z.enum(["CREATE_PAYMENT_LINK", "SEND_REMINDER", "MANUAL_REVIEW"]),
  reasoning: z.string(),
  suggestedRecoveryApproach: z.string()
});

export type CheckoutAbandonmentAIOutput = z.infer<typeof CheckoutAbandonmentAIOutputSchema>;

export async function runAbandonmentAgent(
  candidate: AbandonmentCandidate,
  merchantContext: any
): Promise<CheckoutAbandonmentAIOutput> {
  if (process.env.MOCK_AI === "true") {
    return {
      recommendedAction: "CREATE_PAYMENT_LINK",
      reasoning: "Customer has no successful history but made payment attempts, indicating intent.",
      suggestedRecoveryApproach: "Send a fresh payment link highlighting support."
    };
  }

  const model = AI_MODELS.checkoutRecovery || AI_MODELS.paymentRecovery; // fallback if not explicitly defined

  const prompt = `
You are an expert AI Checkout Abandonment Recovery Agent for Razorpay merchants.
Your goal is to analyze deterministic factual evidence about a likely checkout abandonment candidate and recommend a recovery strategy.

Important Constraints:
1. Do not claim certainty that the customer abandoned the checkout unless explicit telemetry exists. Use wording such as "likely checkout abandonment".
2. Rely strictly on the provided factual evidence. Do not invent customer history or financial values.
3. Recommend actions within the existing Human-in-the-Loop model (e.g., CREATE_PAYMENT_LINK).
4. Do not directly execute actions.

Merchant Name: ${merchantContext.name}
Evidence:
${JSON.stringify(candidate.evidence, null, 2)}
  `;

  const result = await generateObject({
    model,
    schema: CheckoutAbandonmentAIOutputSchema,
    prompt,
    temperature: 0.1,
  });

  return result.object;
}

import crypto from "crypto";
import { prisma as db } from "../../lib/db/prisma";
import { detectCheckoutAbandonment, AbandonmentCandidate } from "./detector";
import { runAbandonmentAgent } from "./agent";

import { scoreAndCreateRecoveryAction } from "../scoring/engine";

export interface AbandonmentRunOptions {
  now?: Date;
  timeoutMinutes?: number;
  severityWeights?: Record<string, number>;
  baseTargetValue?: number;
}

function generateIdempotencyKey(merchantId: string, candidate: AbandonmentCandidate): string {
  const payload = [
    merchantId,
    "CHECKOUT_ABANDONMENT",
    candidate.orderId
  ].join("|");
  return crypto.createHash("sha256").update(payload).digest("hex");
}

export async function processCheckoutAbandonments(merchantId: string, options: AbandonmentRunOptions = {}) {
  const now = options.now || new Date();
  const severityWeights = options.severityWeights;
  const baseTargetValue = options.baseTargetValue;
  const timeoutMinutes = options.timeoutMinutes !== undefined ? options.timeoutMinutes : parseInt(process.env.ABANDONMENT_TIMEOUT_MINUTES || "30", 10);

  const merchant = await db.merchant.findUnique({ where: { id: merchantId } });
  if (!merchant) throw new Error("Merchant not found");

  const candidates = await detectCheckoutAbandonment(merchantId, now, timeoutMinutes);

  const results = [];

  for (const candidate of candidates) {
    const fingerprint = generateIdempotencyKey(merchantId, candidate);

    // Safety check again just to be perfectly sure
    const existing = await db.revenueOpportunity.findFirst({
      where: {
        merchantId,
        source: "CHECKOUT_ABANDONMENT",
        sourceId: fingerprint
      }
    });

    if (existing) {
      continue;
    }

    const aiOutput = await runAbandonmentAgent(candidate, { name: merchant.name });

    const opp = await db.revenueOpportunity.create({
      data: {
        merchantId,
        source: "CHECKOUT_ABANDONMENT",
        sourceId: fingerprint,
        amountSubunits: candidate.evidence.orderAmount,
        currency: candidate.evidence.currency,
        reason: "Likely checkout abandonment candidate",
        status: "OPEN",
        customerId: candidate.customerId,
        orderId: candidate.orderId,
        evidence: candidate.evidence as any,
        metadata: {
          aiAnalysis: aiOutput
        }
      }
    });

    const finalOpp = await scoreAndCreateRecoveryAction(
      opp.id,
      aiOutput,
      aiOutput.recommendedAction,
      { severityWeights, baseTargetValue }
    );

    results.push(finalOpp);
  }

  return results;
}

import { generateObject } from "ai";
import { z } from "zod";
import { AI_MODELS } from "../../ai/config";
import { DetectedAnomaly } from "./analyzer";

export const LeakageAIOutputSchema = z.object({
  whatHappened: z.string().describe("Factual summary of the detected anomaly."),
  whyItMatters: z.string().describe("Revenue and business impact."),
  observedPattern: z.string().describe("The specific pattern observed in the data without assuming external factors."),
  inferredCause: z.string().describe("Likely cause based strictly on the provided evidence. State clearly if the cause cannot be determined."),
  causeConfidence: z.number().min(0).max(1).describe("Confidence in the inferred cause."),
  investigationStrategy: z.string().describe("Recommended strategy for a human to investigate or recover this leakage.")
});

export type LeakageAIOutput = z.infer<typeof LeakageAIOutputSchema>;

export async function runLeakageDetectiveAgent(
  anomaly: DetectedAnomaly,
  merchantContext: any
): Promise<LeakageAIOutput> {
  if (process.env.MOCK_AI === "true") {
    return {
      whatHappened: `Simulated anomaly for ${anomaly.leakageCategory}`,
      whyItMatters: "High impact",
      observedPattern: "Spike detected",
      inferredCause: anomaly.leakageCategory === "DISPUTE_LOSS" ? "Cause cannot be determined from available data" : "Network error",
      causeConfidence: 0.5,
      investigationStrategy: "Review logs"
    };
  }

  const model = AI_MODELS.leakageDetective;

  const prompt = `
You are the AI Revenue Leakage Detective for RecoverAI.
Your goal is to interpret deterministic anomaly evidence and provide clear, factual analysis.

WARNING: You must NEVER invent financial evidence, amounts, counts, percentages, baselines, or affected customers.
You must NEVER state unsupported causes (e.g., "UPI downtime") as facts if the evidence does not establish it.
If the evidence does not clearly point to a cause, explicitly state that the cause cannot be determined.

Merchant Context:
${JSON.stringify(merchantContext, null, 2)}

Detected Anomaly Category: ${anomaly.leakageCategory}

Factual Evidence (Generated by Deterministic Analyzer):
${JSON.stringify(anomaly.evidence, null, 2)}

Provide a structured analysis matching the requested JSON schema.
Distinguish between amount at risk (e.g., failed payments that might be retried) and amount actually lost (e.g., dispute loss where recovery is 0).
`;

  const result = await generateObject({
    model,
    schema: LeakageAIOutputSchema,
    prompt,
    temperature: 0.1,
  });

  return result.object;
}

import { prisma as db } from "../../lib/db/prisma";

export interface DetectiveConfig {
  windowHours: number;
  baselineDays: number;
  paymentFailure: { minCount: number; deviationThresholdPct: number };
  refundLeakage: { minCount: number; deviationThresholdPct: number };
  disputeLoss: { minCount: number };
  subscriptionFailure: { minCount: number; deviationThresholdPct: number };
  paymentLinkExpiry: { minCount: number; deviationThresholdPct: number };
}

export const DEFAULT_CONFIG: DetectiveConfig = {
  windowHours: 6,
  baselineDays: 7,
  paymentFailure: { minCount: 10, deviationThresholdPct: 50 },
  refundLeakage: { minCount: 5, deviationThresholdPct: 50 },
  disputeLoss: { minCount: 2 },
  subscriptionFailure: { minCount: 5, deviationThresholdPct: 50 },
  paymentLinkExpiry: { minCount: 10, deviationThresholdPct: 20 },
};

export interface LeakageEvidence {
  windowStart: string;
  windowEnd: string;
  baselineStart: string;
  baselineEnd: string;
  affectedEventCount: number;
  amountAtRisk: number;
  amountActuallyLost: number;
  baselineMetric: number;
  currentMetric: number;
  percentageChange: number | null;
  primaryGrouping: string | null;
  groupingType: string | null;
}

export interface DetectedAnomaly {
  leakageCategory: string;
  evidence: LeakageEvidence;
}

export async function runDeterministicAnalysis(
  merchantId: string,
  now: Date = new Date(),
  config: DetectiveConfig = DEFAULT_CONFIG
): Promise<DetectedAnomaly[]> {
  const anomalies: DetectedAnomaly[] = [];

  const windowMs = config.windowHours * 60 * 60 * 1000;
  const currentWindowStart = new Date(now.getTime() - windowMs);
  const baselineStart = new Date(now.getTime() - config.baselineDays * 24 * 60 * 60 * 1000);

  // Insufficient data protection
  const oldestEvent = await db.financialEvent.findFirst({
    where: { merchantId },
    orderBy: { occurredAt: 'asc' }
  });

  if (!oldestEvent || oldestEvent.occurredAt > baselineStart) {
    return []; // Return empty if there isn't enough historical data
  }

  // Fetch all relevant events in one go to minimize DB roundtrips
  const events = await db.financialEvent.findMany({
    where: {
      merchantId,
      occurredAt: { gte: baselineStart, lte: now },
      eventType: {
        in: [
          "payment.captured", "payment.failed",
          "refund.created",
          "payment.dispute.created",
          "subscription.halted",
          "payment_link.paid", "payment_link.expired"
        ]
      }
    }
  });

  const currentEvents = events.filter(e => e.occurredAt >= currentWindowStart);
  const baselineEvents = events.filter(e => e.occurredAt < currentWindowStart);

  const baselineWindowCount = (config.baselineDays * 24) / config.windowHours;

  // 1. SYSTEMIC PAYMENT FAILURES (grouped by method)
  const currentPaymentEvents = currentEvents.filter(e => e.eventType.startsWith("payment."));
  const baselinePaymentEvents = baselineEvents.filter(e => e.eventType.startsWith("payment."));

  const methods = new Set<string>();
  events.forEach(e => {
    if (e.eventType.startsWith("payment.") && e.metadata && typeof e.metadata === "object") {
      const meta = e.metadata as any;
      const method = meta?.payload?.payment?.entity?.method;
      if (method) methods.add(method);
    }
  });

  methods.forEach(method => {
    const isMethod = (e: any) => (e.metadata as any)?.payload?.payment?.entity?.method === method;
    const currMethodEvents = currentPaymentEvents.filter(isMethod);
    const baseMethodEvents = baselinePaymentEvents.filter(isMethod);

    const currFailed = currMethodEvents.filter(e => e.eventType === "payment.failed");
    const baseFailed = baseMethodEvents.filter(e => e.eventType === "payment.failed");

    const currFailCount = currFailed.length;
    const baseFailCountAvg = baseFailed.length / Math.max(1, baselineWindowCount);

    if (currFailCount >= config.paymentFailure.minCount) {
      let pctChange = null;
      let anomalous = false;

      if (baseFailCountAvg === 0) {
        anomalous = true;
      } else {
        pctChange = ((currFailCount - baseFailCountAvg) / baseFailCountAvg) * 100;
        if (pctChange >= config.paymentFailure.deviationThresholdPct) {
          anomalous = true;
        }
      }

      if (anomalous) {
        const amountAtRisk = currFailed.reduce((sum, e) => sum + (e.amountSubunits || 0), 0);
        anomalous = true;
        anomalies.push({
          leakageCategory: "SYSTEMIC_PAYMENT_FAILURE",
          evidence: {
            windowStart: currentWindowStart.toISOString(),
            windowEnd: now.toISOString(),
            baselineStart: baselineStart.toISOString(),
            baselineEnd: currentWindowStart.toISOString(),
            affectedEventCount: currFailCount,
            amountAtRisk,
            amountActuallyLost: 0,
            baselineMetric: baseFailCountAvg,
            currentMetric: currFailCount,
            percentageChange: pctChange,
            primaryGrouping: method,
            groupingType: "payment_method"
          }
        });
      }
    }
  });

  // 2. REFUND LEAKAGE
  const currRefunds = currentEvents.filter(e => e.eventType === "refund.created");
  const baseRefunds = baselineEvents.filter(e => e.eventType === "refund.created");

  const currRefundCount = currRefunds.length;
  const baseRefundCountAvg = baseRefunds.length / Math.max(1, baselineWindowCount);

  if (currRefundCount >= config.refundLeakage.minCount) {
    let pctChange = null;
    let anomalous = false;

    if (baseRefundCountAvg === 0) {
      anomalous = true;
    } else {
      pctChange = ((currRefundCount - baseRefundCountAvg) / baseRefundCountAvg) * 100;
      if (pctChange >= config.refundLeakage.deviationThresholdPct) {
        anomalous = true;
      }
    }

    if (anomalous) {
      const amountLost = currRefunds.reduce((sum, e) => sum + (e.amountSubunits || 0), 0);
      anomalies.push({
        leakageCategory: "REFUND_LEAKAGE",
        evidence: {
          windowStart: currentWindowStart.toISOString(),
          windowEnd: now.toISOString(),
          baselineStart: baselineStart.toISOString(),
          baselineEnd: currentWindowStart.toISOString(),
          affectedEventCount: currRefundCount,
          amountAtRisk: 0,
          amountActuallyLost: amountLost, // Refund is actually lost
          baselineMetric: baseRefundCountAvg,
          currentMetric: currRefundCount,
          percentageChange: pctChange,
          primaryGrouping: null,
          groupingType: null
        }
      });
    }
  }

  // 3. DISPUTE LOSS
  const currDisputes = currentEvents.filter(e => e.eventType === "payment.dispute.created");
  const baseDisputes = baselineEvents.filter(e => e.eventType === "payment.dispute.created");

  const currDisputeCount = currDisputes.length;
  const baseDisputeCountAvg = baseDisputes.length / Math.max(1, baselineWindowCount);

  if (currDisputeCount >= config.disputeLoss.minCount) {
    const pctChange = baseDisputeCountAvg === 0 ? null : ((currDisputeCount - baseDisputeCountAvg) / baseDisputeCountAvg) * 100;
    const amountLost = currDisputes.reduce((sum, e) => sum + (e.amountSubunits || 0), 0);
    anomalies.push({
      leakageCategory: "DISPUTE_LOSS",
      evidence: {
        windowStart: currentWindowStart.toISOString(),
        windowEnd: now.toISOString(),
        baselineStart: baselineStart.toISOString(),
        baselineEnd: currentWindowStart.toISOString(),
        affectedEventCount: currDisputeCount,
        amountAtRisk: 0,
        amountActuallyLost: amountLost, // Dispute loss is actually lost
        baselineMetric: baseDisputeCountAvg,
        currentMetric: currDisputeCount,
        percentageChange: pctChange,
        primaryGrouping: null,
        groupingType: null
      }
    });
  }

  // 4. SUBSCRIPTION FAILURE
  const currSubHalts = currentEvents.filter(e => e.eventType === "subscription.halted");
  const baseSubHalts = baselineEvents.filter(e => e.eventType === "subscription.halted");

  const currSubCount = currSubHalts.length;
  const baseSubCountAvg = baseSubHalts.length / Math.max(1, baselineWindowCount);

  if (currSubCount >= config.subscriptionFailure.minCount) {
    let pctChange = null;
    let anomalous = false;

    if (baseSubCountAvg === 0) {
      anomalous = true;
    } else {
      pctChange = ((currSubCount - baseSubCountAvg) / baseSubCountAvg) * 100;
      if (pctChange >= config.subscriptionFailure.deviationThresholdPct) {
        anomalous = true;
      }
    }

    if (anomalous) {
      anomalies.push({
        leakageCategory: "SUBSCRIPTION_FAILURE",
        evidence: {
          windowStart: currentWindowStart.toISOString(),
          windowEnd: now.toISOString(),
          baselineStart: baselineStart.toISOString(),
          baselineEnd: currentWindowStart.toISOString(),
          affectedEventCount: currSubCount,
          amountAtRisk: 0, // Hard to quantify without looking at future invoices, leave as 0
          amountActuallyLost: 0,
          baselineMetric: baseSubCountAvg,
          currentMetric: currSubCount,
          percentageChange: pctChange,
          primaryGrouping: null,
          groupingType: null
        }
      });
    }
  }

  // 5. PAYMENT LINK EXPIRY
  const currPLExpired = currentEvents.filter(e => e.eventType === "payment_link.expired");
  const basePLExpired = baselineEvents.filter(e => e.eventType === "payment_link.expired");

  const currPLExpCount = currPLExpired.length;
  const basePLExpCountAvg = basePLExpired.length / Math.max(1, baselineWindowCount);

  if (currPLExpCount >= config.paymentLinkExpiry.minCount) {
    let pctChange = null;
    let anomalous = false;

    if (basePLExpCountAvg === 0) {
      anomalous = true;
    } else {
      pctChange = ((currPLExpCount - basePLExpCountAvg) / basePLExpCountAvg) * 100;
      if (pctChange >= config.paymentLinkExpiry.deviationThresholdPct) {
        anomalous = true;
      }
    }

    if (anomalous) {
      const amountAtRisk = currPLExpired.reduce((sum, e) => sum + (e.amountSubunits || 0), 0);
      anomalies.push({
        leakageCategory: "PAYMENT_LINK_EXPIRY",
        evidence: {
          windowStart: currentWindowStart.toISOString(),
          windowEnd: now.toISOString(),
          baselineStart: baselineStart.toISOString(),
          baselineEnd: currentWindowStart.toISOString(),
          affectedEventCount: currPLExpCount,
          amountAtRisk: amountAtRisk,
          amountActuallyLost: 0,
          baselineMetric: basePLExpCountAvg,
          currentMetric: currPLExpCount,
          percentageChange: pctChange,
          primaryGrouping: null,
          groupingType: null
        }
      });
    }
  }

  return anomalies;
}

import crypto from "crypto";
import { runDeterministicAnalysis, DetectedAnomaly, DEFAULT_CONFIG, DetectiveConfig } from "./analyzer";
import { runLeakageDetectiveAgent, LeakageAIOutput } from "./agent";
import { prisma as db } from "../../lib/db/prisma";

import { scoreAndCreateRecoveryAction } from "../scoring/engine";

export interface DetectiveRunOptions {
  now?: Date;
  config?: DetectiveConfig;
  severityWeights?: Record<string, number>;
  baseTargetValue?: number;
}

function generateIdempotencyKey(merchantId: string, anomaly: DetectedAnomaly): string {
  const payload = [
    merchantId,
    anomaly.leakageCategory,
    anomaly.evidence.primaryGrouping || "all",
    anomaly.evidence.windowStart,
    anomaly.evidence.windowEnd
  ].join("|");
  return crypto.createHash("sha256").update(payload).digest("hex");
}

export async function executeLeakageDetective(merchantId: string, options: DetectiveRunOptions = {}) {
  const now = options.now || new Date();
  const config = options.config || DEFAULT_CONFIG;
  const severityWeights = options.severityWeights;
  const baseTargetValue = options.baseTargetValue;

  const merchant = await db.merchant.findUnique({ where: { id: merchantId } });
  if (!merchant) throw new Error("Merchant not found");

  const anomalies = await runDeterministicAnalysis(merchantId, now, config);

  const results = [];

  for (const anomaly of anomalies) {
    const fingerprint = generateIdempotencyKey(merchantId, anomaly);
    const existing = await db.revenueOpportunity.findFirst({
      where: {
        merchantId,
        source: "REVENUE_LEAKAGE",
        sourceId: fingerprint
      }
    });

    if (existing) {
      continue; // Skip duplicate
    }

    const aiOutput = await runLeakageDetectiveAgent(anomaly, { name: merchant.name });

    // 1. Create RevenueOpportunity in OPEN state
    const opp = await db.revenueOpportunity.create({
      data: {
        merchantId,
        source: "REVENUE_LEAKAGE",
        sourceId: fingerprint,
        amountSubunits: anomaly.evidence.amountAtRisk || anomaly.evidence.amountActuallyLost || 0,
        currency: "INR",
        reason: aiOutput.whatHappened,
        leakageCategory: anomaly.leakageCategory,
        status: "OPEN",
        evidence: anomaly.evidence as any,
        metadata: {
          aiAnalysis: aiOutput
        }
      }
    });

    // 2. Pass to unified scoring engine
    const finalOpp = await scoreAndCreateRecoveryAction(
      opp.id,
      aiOutput,
      "MANUAL_REVIEW", // Leakage defaults to manual investigation
      { severityWeights, baseTargetValue }
    );

    results.push(finalOpp);
  }

  return results;
}

import { prisma } from '../../lib/db/prisma';
import { createPaymentLinksService } from '../../integrations/razorpay/payment-links';
import { getRazorpayConfig } from '../../lib/config/env';

export async function approveAndExecuteAction(actionId: string) {
    const action = await prisma.recoveryAction.findUnique({
        where: { id: actionId },
        include: { revenueOpportunity: true }
    });

    if (!action || action.status !== 'PENDING_APPROVAL') {
        throw new Error("Action is not valid or not pending approval.");
    }

    if (action.actionType === 'CREATE_PAYMENT_LINK') {
        const configResult = getRazorpayConfig();
        if (!configResult.ok) {
            throw new Error(`Missing Razorpay config: ${configResult.missing.join(', ')}`);
        }
        const paymentLinksService = createPaymentLinksService(configResult.value);

        // Execute Razorpay API
        const link = await paymentLinksService.createPaymentLink({
            amount: action.amountSubunits,
            currency: action.currency,
            description: `Recovery for Opportunity ${action.revenueOpportunityId}`,
            reference_id: action.revenueOpportunityId
        });

        // Update action and opportunity
        await prisma.$transaction(async (tx: any) => {
             await tx.recoveryAction.update({
                 where: { id: actionId },
                 data: {
                     status: 'EXECUTED',
                     // eslint-disable-next-line @typescript-eslint/no-explicit-any
                     razorpayPaymentLinkId: (link as any).id,
                     // eslint-disable-next-line @typescript-eslint/no-explicit-any
                     shortUrl: (link as any).short_url
                 }
             });

             await tx.revenueOpportunity.update({
                 where: { id: action.revenueOpportunityId },
                 data: { status: 'ACTION_EXECUTED' }
             });
        });

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return { success: true, url: (link as any).short_url };
    }

    throw new Error(`Execution for action type ${action.actionType} is not supported.`);
}

import { prisma } from '../../lib/db/prisma';

export class RecoveryPolicy {
  /**
   * Pure function to validate action proposal based on opportunity state.
   */
  static validate(opportunity: any, proposedAmount: number, proposedCurrency: string) {
    if (!opportunity) {
      return { valid: false, reason: "Opportunity not found." };
    }

    if (opportunity.amountSubunits !== proposedAmount || opportunity.currency !== proposedCurrency) {
       return { valid: false, reason: "Amount or currency mismatch." };
    }

    // Check for duplicate active actions
    const activeActions = opportunity.recoveryActions.filter((a: any) => 
      ['PENDING_APPROVAL', 'APPROVED', 'EXECUTED'].includes(a.status)
    );

    if (activeActions.length > 0) {
       return { valid: false, reason: "An active recovery action already exists for this opportunity." };
    }

    if (opportunity.status === 'RECOVERED' || opportunity.status === 'EXPIRED') {
       return { valid: false, reason: "Opportunity is no longer actionable." };
    }

    return { valid: true };
  }

  /**
   * Database wrapper for validate()
   */
  static async validateActionProposal(
    opportunityId: string,
    actionType: string,
    proposedAmount: number,
    proposedCurrency: string
  ): Promise<{ valid: boolean; reason?: string }> {
    const opportunity = await prisma.revenueOpportunity.findUnique({
      where: { id: opportunityId },
      include: { recoveryActions: true }
    });

    return this.validate(opportunity, proposedAmount, proposedCurrency);
  }
}

import { z } from "zod";
import { generateObject } from "ai";
import { AI_MODELS } from "../../ai/config";

export const UnifiedScoringAIOutputSchema = z.object({
  recoveryProbability: z.number()
    .min(0, "recoveryProbability must be at least 0")
    .max(1, "recoveryProbability must be at most 1"),
  reasoning: z.string(),
  urgency: z.enum(["LOW", "MEDIUM", "HIGH", "CRITICAL"])
});

export type UnifiedScoringAIOutput = z.infer<typeof UnifiedScoringAIOutputSchema>;

export async function runUnifiedScoringAgent(
  source: string,
  amountAtRisk: number,
  currency: string,
  domainEvidence: Record<string, any>,
  merchantContext: { name: string }
): Promise<UnifiedScoringAIOutput> {
  if (process.env.MOCK_AI === "true") {
    // Return mock data for synthetic tests
    return {
      recoveryProbability: 0.5,
      reasoning: "Mock AI scoring logic.",
      urgency: "MEDIUM"
    };
  }

  // Use a capable model
  const model = AI_MODELS.paymentRecovery; 

  const prompt = `
You are the Unified AI Recovery Scoring Agent for Razorpay merchants.
Your ONLY task is to estimate the probability that a RevenueOpportunity can be successfully recovered, and to determine its urgency.

Important Constraints:
1. You must ONLY output recoveryProbability (0.0 to 1.0), reasoning, and urgency.
2. DO NOT determine amountAtRisk, expectedRecoveryValue, priorityScore, or any financial amount.
3. Keep your reasoning concise and strictly based on the provided factual evidence.
4. DO NOT invent financial metrics or customer history.

Context:
Merchant Name: ${merchantContext.name}
Opportunity Source: ${source}
Amount At Risk: ${amountAtRisk} ${currency}

Factual Evidence (Including domain analysis):
${JSON.stringify(domainEvidence, null, 2)}
  `;

  const result = await generateObject({
    model,
    schema: UnifiedScoringAIOutputSchema,
    prompt,
    temperature: 0.1,
    maxRetries: 3 // Vercel AI SDK handles retries automatically if Zod validation fails (e.g. out of bounds)
  });

  return result.object;
}

import { prisma as db } from "../../lib/db/prisma";
import { runUnifiedScoringAgent, UnifiedScoringAIOutput } from "./agent";

export const DEFAULT_SEVERITY_WEIGHTS: Record<string, number> = {
  LOW: 1.0,
  MEDIUM: 1.2,
  HIGH: 1.5,
  CRITICAL: 2.0,
};

export interface UnifiedScoringConfig {
  severityWeights?: Record<string, number>;
  baseTargetValue?: number;
}

export function calculateDeterministicPriorityScore(
  amountAtRisk: number,
  recoveryProbability: number,
  urgency: string,
  weights: Record<string, number>,
  baseTargetValue: number
): number {
  const baseValue = amountAtRisk * recoveryProbability;
  const normalizedValue = baseValue / baseTargetValue;
  const weight = weights[urgency] || 1.0;

  const score = normalizedValue * weight;
  return Math.min(100, Math.max(0, score));
}

export async function scoreAndCreateRecoveryAction(
  opportunityId: string,
  domainEvidence: Record<string, any>,
  recommendedAction: string,
  config: UnifiedScoringConfig = {}
) {
  const severityWeights = config.severityWeights || DEFAULT_SEVERITY_WEIGHTS;
  const baseTargetValue = config.baseTargetValue || 10000;

  // 1. Transaction to safely claim the opportunity for scoring
  const opp = await db.$transaction(async (tx) => {
    const existingOpp = await tx.revenueOpportunity.findUnique({
      where: { id: opportunityId },
      include: { recoveryActions: true, merchant: true }
    });

    if (!existingOpp) throw new Error("Opportunity not found");
    if (existingOpp.status !== "OPEN" && existingOpp.status !== "ANALYZED") {
      throw new Error("Opportunity is not in a scorable state");
    }

    // Idempotency: Prevent duplicate scoring actions if one already exists
    if (existingOpp.recoveryActions.length > 0) {
       throw new Error("Recovery action already exists for this opportunity");
    }

    // Lock the opportunity to ANALYZED state to prevent concurrent scorings
    return await tx.revenueOpportunity.update({
      where: { id: opportunityId },
      data: { status: "ANALYZED" },
      include: { merchant: true }
    });
  });

  // 2. Determine if it's unrecoverable strictly by policy
  let aiOutput: UnifiedScoringAIOutput | null = null;
  let finalProbability = 0;
  let urgency = "LOW";
  let reasoning = "Determined deterministically.";

  let skipAI = false;

  if (opp.source === "REVENUE_LEAKAGE" && opp.leakageCategory === "DISPUTE_LOSS") {
    skipAI = true;
    finalProbability = 0.0;
    reasoning = "Dispute losses are categorically unrecoverable by standard recovery actions.";
    urgency = "LOW";
  } else if (opp.source === "REVENUE_LEAKAGE" && opp.leakageCategory === "REFUND_LEAKAGE") {
    // Determine if refund is potentially recoverable (future revenue) vs investigation only
    // If it's investigation only, we still use AI but bound the expected recovery to 0. 
    // Wait, the prompt says "allow scoring only where the opportunity represents potentially recoverable future revenue. Otherwise classify it as investigation-only through deterministic policy."
    // If evidence says amountAtRisk is 0 or null (and only amountActuallyLost exists), it's unrecoverable
    const evidence = opp.evidence as any;
    if (!evidence || !evidence.amountAtRisk || evidence.amountAtRisk === 0) {
      skipAI = true;
      finalProbability = 0.0;
      reasoning = "Refunds without forward-looking at-risk revenue are classified as investigation-only.";
      urgency = "LOW";
    }
  }

  // 3. Consult Unified AI Agent if not deterministic
  if (!skipAI) {
    aiOutput = await runUnifiedScoringAgent(
      opp.source,
      opp.amountSubunits,
      opp.currency,
      { ...domainEvidence, recommendedAction },
      { name: opp.merchant.name }
    );
    finalProbability = aiOutput.recoveryProbability;
    urgency = aiOutput.urgency;
    reasoning = aiOutput.reasoning;
  }

  // 4. Deterministic Calculations
  // Prevent AI from calculating values
  const expectedRecoveryValue = Math.floor(opp.amountSubunits * finalProbability);

  const priorityScore = calculateDeterministicPriorityScore(
    opp.amountSubunits,
    finalProbability,
    urgency,
    severityWeights,
    baseTargetValue
  );

  // 5. Update opportunity and create recovery action
  const finalOpp = await db.$transaction(async (tx) => {
    // Double check status hasn't changed maliciously
    const check = await tx.revenueOpportunity.findUnique({ where: { id: opp.id } });
    if (check?.status !== "ANALYZED") throw new Error("Opportunity status mutated during scoring");

    await tx.revenueOpportunity.update({
      where: { id: opp.id },
      data: {
        priorityScore,
        status: "ACTION_PROPOSED",
      }
    });

    await tx.recoveryAction.create({
      data: {
        revenueOpportunityId: opp.id,
        actionType: skipAI && finalProbability === 0 ? "MANUAL_REVIEW" : recommendedAction,
        status: "PENDING_APPROVAL",
        amountSubunits: opp.amountSubunits,
        currency: opp.currency,
        aiReasoning: reasoning,
        recoveryProbability: finalProbability,
        expectedRecoveryValue: expectedRecoveryValue
      }
    });

    return await tx.revenueOpportunity.findUnique({
      where: { id: opp.id },
      include: { recoveryActions: true }
    });
  });

  return finalOpp;
}

